True def transform(grid):
    h, w = len(grid), len(grid[0])
    rows8 = [r for r,row in enumerate(grid) if 8 in row]
    target = min(rows8)
    out = [[0]*w for _ in range(h)]
    tops = {v:min(r for r,row in enumerate(grid) if v in row) for row in grid for v in row if v}
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v:
                out[target + r - tops[v]][c] = v
    return out
